import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_01_package_boundary.png",c="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_02_plugin_lifecycle.png",l="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_03_path_conversion.png",d="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_04_ceres_problem.png",s="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_05_residuals.png",n="/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_06_upsampling.png",P=JSON.parse('{"title":"一条折线路径如何被“拉顺又避障”？逐函数拆解 Nav2 Constrained Smoother 的 29 个入口","description":"nav2constrainedsmoother 不是给路径做简单均值滤波。它把路径点坐标交给 Ceres Solver，把平滑度、最小转弯半径、原路径偏移和 Costmap 代价同时写进一个非线性最小二乘问题，再把优化后的稀疏点恢复成带朝向的 navmsgs/Path。","frontmatter":{"title":"一条折线路径如何被“拉顺又避障”？逐函数拆解 Nav2 Constrained Smoother 的 29 个入口","description":"nav2constrainedsmoother 不是给路径做简单均值滤波。它把路径点坐标交给 Ceres Solver，把平滑度、最小转弯半径、原路径偏移和 Costmap 代价同时写进一个非线性最小二乘问题，再把优化后的稀疏点恢复成带朝向的 navmsgs/Path。","date":"2026-07-29","topic":"Nav2 工程实践","section":"五 · 平滑器与基础工具","readingTime":24,"source":"2026-07-29/nav2_constrained_smoother_source_walkthrough.md","status":"archived","cover":"/article-assets/2026-07-29/nav2_constrained_smoother_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-constrained-smoother-source-walkthrough"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一条折线路径如何被“拉顺又避障”？逐函数拆解 Nav2 Constrained Smoother 的 29 个入口"}],["meta",{"property":"og:description","content":"nav2constrainedsmoother 不是给路径做简单均值滤波。它把路径点坐标交给 Ceres Solver，把平滑度、最小转弯半径、原路径偏移和 Costmap 代价同时写进一个非线性最小二乘问题，再把优化后的稀疏点恢复成带朝向的 navmsgs/Path。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-constrained-smoother-source-walkthrough"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-29"}],["meta",{"name":"twitter:title","content":"一条折线路径如何被“拉顺又避障”？逐函数拆解 Nav2 Constrained Smoother 的 29 个入口"}],["meta",{"name":"twitter:description","content":"nav2constrainedsmoother 不是给路径做简单均值滤波。它把路径点坐标交给 Ceres Solver，把平滑度、最小转弯半径、原路径偏移和 Costmap 代价同时写进一个非线性最小二乘问题，再把优化后的稀疏点恢复成带朝向的 navmsgs/Path。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-29/nav2_constrained_smoother_01_package_boundary.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/nav2-constrained-smoother-source-walkthrough-2026-07-29.md","filePath":"archive/nav2-constrained-smoother-source-walkthrough-2026-07-29.md","lastUpdated":null}'),h={name:"archive/nav2-constrained-smoother-source-walkthrough-2026-07-29.md"};function m(u,e,p,_,b,C){return a(),t("div",null,[...e[0]||(e[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/nav2/nav2-constrained-smoother-source-walkthrough">当前版本</a>。</p></blockquote><h1 id="一条折线路径如何被-拉顺又避障-逐函数拆解-nav2-constrained-smoother-的-29-个入口" tabindex="-1">一条折线路径如何被“拉顺又避障”？逐函数拆解 Nav2 Constrained Smoother 的 29 个入口 <a class="header-anchor" href="#一条折线路径如何被-拉顺又避障-逐函数拆解-nav2-constrained-smoother-的-29-个入口" aria-label="Permalink to &quot;一条折线路径如何被“拉顺又避障”？逐函数拆解 Nav2 Constrained Smoother 的 29 个入口&quot;">​</a></h1><p><code>nav2_constrained_smoother</code> 不是给路径做简单均值滤波。它把路径点坐标交给 Ceres Solver，把平滑度、最小转弯半径、原路径偏移和 Costmap 代价同时写进一个非线性最小二乘问题，再把优化后的稀疏点恢复成带朝向的 <code>nav_msgs/Path</code>。</p><p>这套实现尤其照顾 Reeds-Shepp 路径中的前进／倒退切换。方向发生变化的位置称为 Cusp，机器人通常会在附近做大幅转向，因此源码会在 Cusp 两侧提高 Costmap 权重。它也支持从机器人坐标系选取多个检查点，而不只检查路径中心。</p><p>本文以本地 <code>navigation2</code>、包版本 <code>1.1.20</code> 为事实基线。生产范围包括 5 个头文件和 1 个实现文件，共 29 个显式函数入口；测试夹具和测试辅助函数不计入这个数字。</p><h2 id="一、先把结论说清楚" tabindex="-1">一、先把结论说清楚 <a class="header-anchor" href="#一、先把结论说清楚" aria-label="Permalink to &quot;一、先把结论说清楚&quot;">​</a></h2><h3 id="_1-1-它优化的是路径几何-不是速度" tabindex="-1">1.1 它优化的是路径几何，不是速度 <a class="header-anchor" href="#_1-1-它优化的是路径几何-不是速度" aria-label="Permalink to &quot;1.1 它优化的是路径几何，不是速度&quot;">​</a></h3><p>插件输入和输出都是 <code>nav_msgs/Path</code>。它修改 Pose 的二维位置与偏航角，不读取里程计，不计算 <code>cmd_vel</code>，也不决定控制器如何跟踪。速度、加速度和控制频率仍属于 Controller 与 Velocity Smoother 的职责。</p><h3 id="_1-2-它是软约束优化器-不是碰撞硬约束求解器" tabindex="-1">1.2 它是软约束优化器，不是碰撞硬约束求解器 <a class="header-anchor" href="#_1-2-它是软约束优化器-不是碰撞硬约束求解器" aria-label="Permalink to &quot;1.2 它是软约束优化器，不是碰撞硬约束求解器&quot;">​</a></h3><p>Costmap、曲率、平滑和原路径距离都以残差形式进入 Ceres。高代价会推动路径远离障碍，但源码没有把碰撞区域设成绝对不可行域。因此，<code>SmoothPath</code> Goal 中的 <code>check_for_collisions</code> 仍有价值：插件返回后，<code>nav2_smoother</code> 可以再按 Footprint 对整条结果做硬碰撞检查。</p><h3 id="_1-3-它适合有界路径段" tabindex="-1">1.3 它适合有界路径段 <a class="header-anchor" href="#_1-3-它适合有界路径段" aria-label="Permalink to &quot;1.3 它适合有界路径段&quot;">​</a></h3><p>Ceres 对路径中的优化点建立参数块和残差块，路径越长，问题越大。包 README 明确建议平滑长度受控的局部路径段，也明确不支持连续多个 Pose 位于同一坐标的原地旋转路径。实际 BT 可以在平滑前用 <code>TruncatePathLocal</code> 截取机器人附近的路径，并以距离条件周期触发。</p><h3 id="_1-4-当前项目尚未在生产参数中选用它" tabindex="-1">1.4 当前项目尚未在生产参数中选用它 <a class="header-anchor" href="#_1-4-当前项目尚未在生产参数中选用它" aria-label="Permalink to &quot;1.4 当前项目尚未在生产参数中选用它&quot;">​</a></h3><p>当前仓库的生产 YAML 都把 <code>smoother_plugins</code> 指向 <code>simple_smoother</code>。本包已正确导出 <code>nav2_constrained_smoother/ConstrainedSmoother</code>，但只有本包 README 和平滑器基准工具给出了启用示例。阅读本文得到的是当前源码能力，不代表现有 Bringup 已经运行该插件。</p><h2 id="二、包边界与完整调用链" tabindex="-1">二、包边界与完整调用链 <a class="header-anchor" href="#二、包边界与完整调用链" aria-label="Permalink to &quot;二、包边界与完整调用链&quot;">​</a></h2><h3 id="_2-1-从-bt-到插件的同步调用" tabindex="-1">2.1 从 BT 到插件的同步调用 <a class="header-anchor" href="#_2-1-从-bt-到插件的同步调用" aria-label="Permalink to &quot;2.1 从 BT 到插件的同步调用&quot;">​</a></h3><p>行为树 <code>SmoothPath</code> 节点把未平滑路径、插件 ID、最大平滑时长和碰撞检查开关写进 <code>nav2_msgs/action/SmoothPath</code> Goal。<code>nav2_smoother::SmootherServer</code> 接收 Goal，通过 Pluginlib 找到已加载的插件，把 Goal Path 复制到 Result Path，然后同步调用插件的 <code>smooth()</code>。</p><p>插件内部没有 ROS Topic 回调，也没有自己的 Action Server。它的主计算发生在 Smoother Server 的 Action 执行线程中。Ceres 返回后，Smoother Server 记录耗时、发布 <code>/plan_smoothed</code>，按 Goal 要求执行 Footprint 碰撞检查，最后把结果交还 BT。</p><p><img src="'+r+'" alt="nav2_constrained_smoother 包边界与上下游数据流"></p><h3 id="_2-2-包内数据如何分层" tabindex="-1">2.2 包内数据如何分层 <a class="header-anchor" href="#_2-2-包内数据如何分层" aria-label="Permalink to &quot;2.2 包内数据如何分层&quot;">​</a></h3><ul><li><code>ConstrainedSmoother</code> 是 <code>nav2_core::Smoother</code> 插件壳体，负责 Lifecycle 接口、ROS 参数、Path 消息与 Eigen 数据转换。</li><li><code>Smoother</code> 负责 Ceres 配置、路径下采样、问题构建、求解以及上采样。</li><li><code>SmootherCostFunction</code> 负责单个中间点对应的四维残差。</li><li><code>SmootherParams</code> 与 <code>OptimizerParams</code> 负责参数读取和有限校验。</li><li><code>arcCenter()</code>、<code>tangentDir()</code> 与 <code>cubicBezier()</code> 负责圆弧、切向和插值几何。</li></ul><h2 id="三、插件壳体的七个函数" tabindex="-1">三、插件壳体的七个函数 <a class="header-anchor" href="#三、插件壳体的七个函数" aria-label="Permalink to &quot;三、插件壳体的七个函数&quot;">​</a></h2><h3 id="_3-1-constrainedsmoother-constrainedsmoother" tabindex="-1">3.1 <code>ConstrainedSmoother::ConstrainedSmoother()</code> <a class="header-anchor" href="#_3-1-constrainedsmoother-constrainedsmoother" aria-label="Permalink to &quot;3.1 `ConstrainedSmoother::ConstrainedSmoother()`&quot;">​</a></h3><ul><li>作用：默认构造插件对象，不主动创建订阅器、线程或 Ceres 问题。</li><li>输入：没有显式输入。</li><li>输出：一个尚未配置的 <code>ConstrainedSmoother</code> 实例。</li><li>数据流／回调：Pluginlib 创建实例时触发，后续必须由 Smoother Server 调用 <code>configure()</code>。</li><li>包外调用：调用点位于 <code>nav2_smoother::SmootherServer::loadSmootherPlugins()</code> 的 <code>createUniqueInstance()</code> 内部。</li></ul><h3 id="_3-2-constrainedsmoother-constrainedsmoother" tabindex="-1">3.2 <code>ConstrainedSmoother::~ConstrainedSmoother()</code> <a class="header-anchor" href="#_3-2-constrainedsmoother-constrainedsmoother" aria-label="Permalink to &quot;3.2 `ConstrainedSmoother::~ConstrainedSmoother()`&quot;">​</a></h3><ul><li>作用：使用默认析构流程释放内部 <code>unique_ptr&lt;Smoother&gt;</code> 和共享引用。</li><li>输入：没有显式输入。</li><li>输出：没有返回值。</li><li>数据流／回调：插件容器清空或 Smoother Server 生命周期结束时触发。</li><li>包外调用：由 C++ 对象生命周期和 Pluginlib 管理，不是 ROS 回调。</li></ul><h3 id="_3-3-constrainedsmoother-configure" tabindex="-1">3.3 <code>ConstrainedSmoother::configure()</code> <a class="header-anchor" href="#_3-3-constrainedsmoother-configure" aria-label="Permalink to &quot;3.3 `ConstrainedSmoother::configure()`&quot;">​</a></h3><ul><li>作用：把插件接到 Smoother Server 的运行环境，读取两组参数并初始化内部求解器。</li><li>输入：Lifecycle Node 弱引用、插件实例名、TF Buffer、Costmap Subscriber 和 Footprint Subscriber。</li><li>输出：没有返回值；成员 <code>costmap_sub_</code>、<code>tf_</code>、<code>plugin_name_</code>、<code>logger_</code>、<code>smoother_</code>、<code>optimizer_params_</code> 和 <code>smoother_params_</code> 被填充。</li><li>数据流／回调：先锁定父节点；失败就抛出 <code>runtime_error</code>。随后构造内部 <code>Smoother</code>，调用 <code>OptimizerParams::get()</code>、<code>SmootherParams::get()</code> 和 <code>Smoother::initialize()</code>。</li><li>包外调用：由 <code>SmootherServer::loadSmootherPlugins()</code> 在插件实例创建后调用。</li></ul><p>这个函数接收了 TF 和 Footprint Subscriber，但当前算法只保存 TF、完全忽略 Footprint 参数；后续计算也不读取 TF。真正被优化器使用的是 Costmap Subscriber。Footprint 碰撞检查在包外的 Smoother Server 中完成。</p><h3 id="_3-4-constrainedsmoother-cleanup" tabindex="-1">3.4 <code>ConstrainedSmoother::cleanup()</code> <a class="header-anchor" href="#_3-4-constrainedsmoother-cleanup" aria-label="Permalink to &quot;3.4 `ConstrainedSmoother::cleanup()`&quot;">​</a></h3><ul><li>作用：响应 Lifecycle 清理阶段并记录插件名。</li><li>输入：没有显式输入，读取 <code>logger_</code> 与 <code>plugin_name_</code>。</li><li>输出：没有返回值，也没有主动重置成员资源。</li><li>数据流／回调：Smoother Server 的 <code>on_cleanup()</code> 遍历插件表时调用。</li><li>包外调用：位于 <code>nav2_smoother</code> 包的 Lifecycle 清理链。</li></ul><h3 id="_3-5-constrainedsmoother-activate" tabindex="-1">3.5 <code>ConstrainedSmoother::activate()</code> <a class="header-anchor" href="#_3-5-constrainedsmoother-activate" aria-label="Permalink to &quot;3.5 `ConstrainedSmoother::activate()`&quot;">​</a></h3><ul><li>作用：响应 Lifecycle 激活阶段并记录日志。</li><li>输入：没有显式输入。</li><li>输出：没有返回值。</li><li>数据流／回调：不创建线程、不启动定时器，也不激活发布器。</li><li>包外调用：Smoother Server 的 <code>on_activate()</code> 在激活 Action Server 前调用所有插件的 <code>activate()</code>。</li></ul><h3 id="_3-6-constrainedsmoother-deactivate" tabindex="-1">3.6 <code>ConstrainedSmoother::deactivate()</code> <a class="header-anchor" href="#_3-6-constrainedsmoother-deactivate" aria-label="Permalink to &quot;3.6 `ConstrainedSmoother::deactivate()`&quot;">​</a></h3><ul><li>作用：响应 Lifecycle 停用阶段并记录日志。</li><li>输入：没有显式输入。</li><li>输出：没有返回值。</li><li>数据流／回调：不取消 Ceres 任务，也不释放内部平滑器。</li><li>包外调用：Smoother Server 的 <code>on_deactivate()</code> 在停用链中调用。</li></ul><h3 id="_3-7-constrainedsmoother-smooth" tabindex="-1">3.7 <code>ConstrainedSmoother::smooth()</code> <a class="header-anchor" href="#_3-7-constrainedsmoother-smooth" aria-label="Permalink to &quot;3.7 `ConstrainedSmoother::smooth()`&quot;">​</a></h3><ul><li>作用：完成 ROS Path 与内部优化数据之间的全部适配。</li><li>输入：可原地修改的 <code>nav_msgs::Path &amp; path</code>，以及 Action Goal 给出的最大平滑时长。</li><li>输出：成功时返回 <code>true</code>，并以优化后的 Pose 序列覆盖原 Path；Ceres 解不可用时走失败分支。</li><li>数据流／回调：少于两个 Pose 时直接返回成功。普通路径会逐点读取位置和四元数偏航角，把数据编成 <code>(x, y, direction_sign)</code>；内部求解完成后再把第三维改写为偏航角并恢复成四元数。</li><li>包外调用：由 <code>SmootherServer::smoothPlan()</code> 同步调用。插件只改 Result Path，不发布 Topic。</li></ul><p><code>direction_sign</code> 不是偏航角。当前点朝向向量与“当前点到下一点”的位移向量点积小于零时，源码把该段标成 <code>-1</code>，否则标成 <code>+1</code>。末点没有后继段，因此复制倒数位置对应的方向符号。起点和终点的原始朝向单独保存在 <code>start_dir</code>、<code>end_dir</code>，供输出重建使用。</p><p><img src="'+c+'" alt="Pluginlib 加载、Lifecycle 与 smooth 回调链"></p><h2 id="四、参数结构的四个函数" tabindex="-1">四、参数结构的四个函数 <a class="header-anchor" href="#四、参数结构的四个函数" aria-label="Permalink to &quot;四、参数结构的四个函数&quot;">​</a></h2><h3 id="_4-1-smootherparams-smootherparams" tabindex="-1">4.1 <code>SmootherParams::SmootherParams()</code> <a class="header-anchor" href="#_4-1-smootherparams-smootherparams" aria-label="Permalink to &quot;4.1 `SmootherParams::SmootherParams()`&quot;">​</a></h3><ul><li>作用：构造平滑参数容器。</li><li>输入：没有显式输入。</li><li>输出：成员使用类内初值，其中权重初值多为零，采样因子为一，前进／倒退识别和端点朝向保持默认开启。</li><li>数据流／回调：真正的运行默认值并不只由这些初值决定，<code>get()</code> 会从 ROS 参数读取声明值。</li><li>包外调用：由 <code>ConstrainedSmoother</code> 成员构造自动触发。</li></ul><h3 id="_4-2-smootherparams-get" tabindex="-1">4.2 <code>SmootherParams::get()</code> <a class="header-anchor" href="#_4-2-smootherparams-get" aria-label="Permalink to &quot;4.2 `SmootherParams::get()`&quot;">​</a></h3><ul><li>作用：声明并读取平滑算法全部 ROS 参数。</li><li>输入：Lifecycle Node 裸指针与插件实例名，例如 <code>SmoothPath</code>。</li><li>输出：填充最大曲率、四类基础权重、Cusp 权重、Cusp 区域长度、Costmap 检查点、上下采样因子、倒车识别和端点朝向策略。</li><li>数据流／回调：参数名都以插件实例名为前缀。<code>minimum_turning_radius</code> 被换算为 <code>max_curvature=1/radius</code>；<code>w_cost_cusp_multiplier</code> 与 <code>w_cost</code> 相乘得到 Cusp 中心权重。</li><li>包外调用：只由 <code>ConstrainedSmoother::configure()</code> 调用，不是动态参数回调。</li></ul><p><code>cost_check_points</code> 按 <code>[x, y, weight]</code> 三元组解释。元素数不能被三整除时立即抛出 <code>runtime_error</code>。各检查点权重随后按总和归一化，但源码没有拒绝“非空且权重总和为零”的配置，这种输入会在归一化时产生非有限值。</p><h3 id="_4-3-optimizerparams-optimizerparams" tabindex="-1">4.3 <code>OptimizerParams::OptimizerParams()</code> <a class="header-anchor" href="#_4-3-optimizerparams-optimizerparams" aria-label="Permalink to &quot;4.3 `OptimizerParams::OptimizerParams()`&quot;">​</a></h3><ul><li>作用：给 Ceres 配置结构体设置初始值。</li><li>输入：没有显式输入。</li><li>输出：<code>debug=false</code>、<code>max_iterations=50</code>，以及参数、函数、梯度三类容差的结构体初值。</li><li>数据流／回调：这些值会被 <code>get()</code> 读取的 ROS 参数覆盖。</li><li>包外调用：由 <code>ConstrainedSmoother</code> 成员构造自动触发。</li></ul><h3 id="_4-4-optimizerparams-get" tabindex="-1">4.4 <code>OptimizerParams::get()</code> <a class="header-anchor" href="#_4-4-optimizerparams-get" aria-label="Permalink to &quot;4.4 `OptimizerParams::get()`&quot;">​</a></h3><ul><li>作用：读取并校验 Ceres 线性求解器与停止条件。</li><li>输入：Lifecycle Node 裸指针与插件实例名。</li><li>输出：填充 <code>linear_solver_type</code>、<code>param_tol</code>、<code>fn_tol</code>、<code>gradient_tol</code>、<code>max_iterations</code> 和 <code>debug</code>。</li><li>数据流／回调：当前只允许 <code>DENSE_QR</code> 与 <code>SPARSE_NORMAL_CHOLESKY</code>。非法字符串会打印全部可选值并抛出 <code>runtime_error</code>。</li><li>包外调用：由 <code>ConstrainedSmoother::configure()</code> 调用。</li></ul><p>这些参数只在配置阶段读取。当前包没有注册动态参数回调，运行中修改参数不会自动重建 <code>SmootherParams</code> 或 <code>ceres::Solver::Options</code>。</p><h2 id="五、内部求解器的七个函数" tabindex="-1">五、内部求解器的七个函数 <a class="header-anchor" href="#五、内部求解器的七个函数" aria-label="Permalink to &quot;五、内部求解器的七个函数&quot;">​</a></h2><h3 id="_5-1-smoother-smoother" tabindex="-1">5.1 <code>Smoother::Smoother()</code> <a class="header-anchor" href="#_5-1-smoother-smoother" aria-label="Permalink to &quot;5.1 `Smoother::Smoother()`&quot;">​</a></h3><ul><li>作用：构造内部求解器对象。</li><li>输入：没有显式输入。</li><li>输出：一个尚未写入 Ceres Options 的 <code>Smoother</code>。</li><li>数据流／回调：不建立 Costmap 网格，不分配路径参数块。</li><li>包外调用：由 <code>ConstrainedSmoother::configure()</code> 通过 <code>make_unique</code> 创建。</li></ul><h3 id="_5-2-smoother-smoother" tabindex="-1">5.2 <code>Smoother::~Smoother()</code> <a class="header-anchor" href="#_5-2-smoother-smoother" aria-label="Permalink to &quot;5.2 `Smoother::~Smoother()`&quot;">​</a></h3><ul><li>作用：析构求解器对象及其持有的 Costmap 网格共享指针。</li><li>输入：没有显式输入。</li><li>输出：没有返回值。</li><li>数据流／回调：默认析构，不执行 Ceres 取消或 ROS 清理。</li><li>包外调用：随插件对象释放。</li></ul><h3 id="_5-3-smoother-initialize" tabindex="-1">5.3 <code>Smoother::initialize()</code> <a class="header-anchor" href="#_5-3-smoother-initialize" aria-label="Permalink to &quot;5.3 `Smoother::initialize()`&quot;">​</a></h3><ul><li>作用：把 ROS 层读取到的优化器参数映射为 <code>ceres::Solver::Options</code>。</li><li>输入：按值传入的 <code>OptimizerParams</code>。</li><li>输出：更新线性求解器类型、最大迭代数、三类容差和日志策略。</li><li>数据流／回调：调试开启时逐迭代输出进度；关闭时设置为静默。</li><li>包外调用：只由插件 <code>configure()</code> 调用。</li></ul><p>最大求解时间没有在这里设置，因为它来自每个 <code>SmoothPath</code> Goal。真正求解前，<code>Smoother::smooth()</code> 才把 <code>params.max_time</code> 写进 <code>max_solver_time_in_seconds</code>。</p><h3 id="_5-4-smoother-smooth" tabindex="-1">5.4 <code>Smoother::smooth()</code> <a class="header-anchor" href="#_5-4-smoother-smooth" aria-label="Permalink to &quot;5.4 `Smoother::smooth()`&quot;">​</a></h3><ul><li>作用：组织一次完整的 Ceres 求解。</li><li>输入：带方向符号的 Eigen 路径、起终点方向向量、只读 Costmap 和本次平滑参数。</li><li>输出：原地更新 Eigen 路径；可用解返回 <code>true</code>，不可用或代价变差返回 <code>false</code>。</li><li>数据流／回调：创建局部 <code>ceres::Problem</code>、优化路径副本和优化标志，调用 <code>buildProblem()</code>；有可优化变量时运行 <code>ceres::Solve()</code>，随后无论是否真正建模都调用 <code>upsampleAndPopulate()</code>。</li><li>包外调用：只由 <code>ConstrainedSmoother::smooth()</code> 调用。</li></ul><p>路径少于两个点会在这里抛出 <code>runtime_error</code>，不过外层插件已经对少于两个 Pose 的情况提前返回。求解结果只检查 <code>IsSolutionUsable()</code> 和“最终代价是否高于初始代价”。源码没有检查 Ceres 的终止类型，所以时间上限触发后，只要仍有可用且未变差的解，函数仍可能返回成功。</p><h3 id="_5-5-smoother-buildproblem" tabindex="-1">5.5 <code>Smoother::buildProblem()</code> <a class="header-anchor" href="#_5-5-smoother-buildproblem" aria-label="Permalink to &quot;5.5 `Smoother::buildProblem()`&quot;">​</a></h3><ul><li>作用：把路径和 Costmap 变成 Ceres 参数块、残差块与常量块。</li><li>输入：原路径、Costmap、平滑参数，以及四个输出容器。</li><li>输出：填充 <code>problem</code>、<code>path_optim</code> 和 <code>optimized</code>；存在可优化中间 Pose 时返回 <code>true</code>。</li><li>数据流／回调：复制 Costmap 字节数组到 Ceres Grid，建立双三次插值器；遍历路径时执行下采样、Cusp 识别、Cusp 前后权重更新和三点残差块创建。</li><li>包外调用：只由内部 <code>smooth()</code> 调用。</li></ul><p>每个残差块连接前一优化点、当前优化中心点和后一优化点。首点与末点始终设为常量；要求保持起点朝向时，紧邻起点的点也固定；要求保持目标朝向时，紧邻终点的点也固定。扣除这些约束后没有可优化 Pose，就返回 <code>false</code>，上层会直接进入路径重建。</p><h3 id="_5-6-smoother-upsampleandpopulate" tabindex="-1">5.6 <code>Smoother::upsampleAndPopulate()</code> <a class="header-anchor" href="#_5-6-smoother-upsampleandpopulate" aria-label="Permalink to &quot;5.6 `Smoother::upsampleAndPopulate()`&quot;">​</a></h3><ul><li>作用：把稀疏优化结果恢复为完整路径，并为每个点计算朝向。</li><li>输入：优化路径、优化标志、起终点方向、采样参数和输出路径引用。</li><li>输出：清空并重新填充最终 Eigen 路径，第三维由方向符号变成偏航角。</li><li>数据流／回调：遍历实际参与优化的节点，在相邻节点间按采样因子插入三次贝塞尔点；利用三点切向计算中间朝向，并按前进／倒退符号修正方向。</li><li>包外调用：只由内部 <code>smooth()</code> 调用。</li></ul><p><code>path_upsampling_factor=0</code> 时保留下采样后的优化节点；取值为一时按原索引间隔恢复原粒度；大于一时产生比原路径更多的点。这里恢复的是几何密度，不是重新运行碰撞检查。</p><h3 id="_5-7-smoother-cubicbezier" tabindex="-1">5.7 <code>Smoother::cubicBezier()</code> <a class="header-anchor" href="#_5-7-smoother-cubicbezier" aria-label="Permalink to &quot;5.7 `Smoother::cubicBezier()`&quot;">​</a></h3><ul><li>作用：计算三次贝塞尔曲线上的二维点。</li><li>输入：端点 <code>pt0</code>、<code>pt3</code>，控制点 <code>pt1</code>、<code>pt2</code>，以及插值比例 <code>mu</code>。</li><li>输出：比例位置对应的二维坐标。</li><li>数据流／回调：<code>upsampleAndPopulate()</code> 以端点切向和两点距离构造控制点，控制臂长度固定为段长的 <code>0.4</code> 倍。</li><li>包外调用：没有包外调用，仅用于内部路径重采样。</li></ul><p><img src="'+l+'" alt="Path 消息、方向符号、Ceres 输入与 Path 写回"></p><h2 id="六、代价函数的九个函数" tabindex="-1">六、代价函数的九个函数 <a class="header-anchor" href="#六、代价函数的九个函数" aria-label="Permalink to &quot;六、代价函数的九个函数&quot;">​</a></h2><h3 id="_6-1-smoothercostfunction-smoothercostfunction" tabindex="-1">6.1 <code>SmootherCostFunction::SmootherCostFunction()</code> <a class="header-anchor" href="#_6-1-smoothercostfunction-smoothercostfunction" aria-label="Permalink to &quot;6.1 `SmootherCostFunction::SmootherCostFunction()`&quot;">​</a></h3><ul><li>作用：为一个待优化中心点保存残差计算上下文。</li><li>输入：中心点原始位置、后一段与前一段的长度比、倒车标志、Costmap、共享双三次插值器、平滑参数和当前 Costmap 权重。</li><li>输出：一个可被 Ceres 自动微分包装的函数对象。</li><li>数据流／回调：同时缓存 Costmap 原点和分辨率，后续把世界坐标换成网格连续坐标。</li><li>包外调用：由 <code>Smoother::buildProblem()</code> 为每个可建模中间点创建。</li></ul><p>长度比带有方向语义。普通点使用正比值，Cusp 点使用负比值，让平滑残差和曲率几何把前进／倒退切换视为运动方向反转，而不是把两段当成普通连续前进。</p><h3 id="_6-2-smoothercostfunction-autodiff" tabindex="-1">6.2 <code>SmootherCostFunction::AutoDiff()</code> <a class="header-anchor" href="#_6-2-smoothercostfunction-autodiff" aria-label="Permalink to &quot;6.2 `SmootherCostFunction::AutoDiff()`&quot;">​</a></h3><ul><li>作用：把函数对象包装成 Ceres 自动微分代价函数。</li><li>输入：隐式使用当前对象。</li><li>输出：动态分配的 <code>ceres::CostFunction *</code>。</li><li>数据流／回调：声明四维残差和三组二维参数块，分别对应中心点、后一节点和前一节点。</li><li>包外调用：<code>buildProblem()</code> 把返回对象交给 <code>Problem::AddResidualBlock()</code>，所有权随后由 Ceres Problem 管理。</li></ul><h3 id="_6-3-smoothercostfunction-setcostmapweight" tabindex="-1">6.3 <code>SmootherCostFunction::setCostmapWeight()</code> <a class="header-anchor" href="#_6-3-smoothercostfunction-setcostmapweight" aria-label="Permalink to &quot;6.3 `SmootherCostFunction::setCostmapWeight()`&quot;">​</a></h3><ul><li>作用：更新某个路径点的障碍代价权重。</li><li>输入：新的双精度权重。</li><li>输出：没有返回值，成员 <code>costmap_weight_</code> 被覆盖。</li><li>数据流／回调：发现 Cusp 时，<code>buildProblem()</code> 会回看半个 Cusp 区域内已创建的代价函数，把权重向 Cusp 中心值渐变。</li><li>包外调用：没有包外调用。</li></ul><h3 id="_6-4-smoothercostfunction-getcostmapweight" tabindex="-1">6.4 <code>SmootherCostFunction::getCostmapWeight()</code> <a class="header-anchor" href="#_6-4-smoothercostfunction-getcostmapweight" aria-label="Permalink to &quot;6.4 `SmootherCostFunction::getCostmapWeight()`&quot;">​</a></h3><ul><li>作用：读取某个路径点当前的障碍代价权重。</li><li>输入：没有显式输入。</li><li>输出：<code>costmap_weight_</code>。</li><li>数据流／回调：用于比较同一残差函数是否已经被另一个更近的 Cusp 赋予更强权重，避免较弱更新覆盖更强更新。</li><li>包外调用：没有包外调用。</li></ul><h3 id="_6-5-smoothercostfunction-operator" tabindex="-1">6.5 <code>SmootherCostFunction::operator()</code> <a class="header-anchor" href="#_6-5-smoothercostfunction-operator" aria-label="Permalink to &quot;6.5 `SmootherCostFunction::operator()`&quot;">​</a></h3><ul><li>作用：为 Ceres 计算一个中心点对应的四维残差。</li><li>输入：中心点、后一节点、前一节点的二维参数指针，以及四维输出数组。</li><li>输出：依次写入平滑残差、曲率残差、原路径距离残差和 Costmap 残差，返回 <code>true</code>。</li><li>数据流／回调：Ceres 在自动微分和迭代求解过程中反复调用；模板类型可能是普通浮点数，也可能是携带导数的 Jet。</li><li>包外调用：只由 Ceres Solver 间接调用。</li></ul><p>需要准确理解“残差”这个词。四个子函数写入的值本身已经含有权重和平方距离，Ceres 又最小化残差向量的平方和。因此最终目标不是四个注释公式的简单相加，而是这些残差分量再次平方后的总和。</p><h3 id="_6-6-smoothercostfunction-addsmoothingresidual" tabindex="-1">6.6 <code>SmootherCostFunction::addSmoothingResidual()</code> <a class="header-anchor" href="#_6-6-smoothercostfunction-addsmoothingresidual" aria-label="Permalink to &quot;6.6 `SmootherCostFunction::addSmoothingResidual()`&quot;">​</a></h3><ul><li>作用：抑制相邻路径段的方向和长度突变。</li><li>输入：平滑权重、中心点、前后节点和一个残差引用。</li><li>输出：向残差加入带权的位移差平方。</li><li>数据流／回调：后一位移先乘“后一段／前一段长度比”，再与前一位移比较；Cusp 使用负比值，等价于先翻转一侧运动方向再检查连续性。</li><li>包外调用：只由 <code>operator()</code> 调用。</li></ul><h3 id="_6-7-smoothercostfunction-addcurvatureresidual" tabindex="-1">6.7 <code>SmootherCostFunction::addCurvatureResidual()</code> <a class="header-anchor" href="#_6-7-smoothercostfunction-addcurvatureresidual" aria-label="Permalink to &quot;6.7 `SmootherCostFunction::addCurvatureResidual()`&quot;">​</a></h3><ul><li>作用：只惩罚超过允许上限的曲率。</li><li>输入：曲率权重、三点坐标和残差引用。</li><li>输出：直线、退化圆弧或未超限时不改变残差；超限时加入 <code>weight × (curvature-max_curvature)²</code>。</li><li>数据流／回调：先调用 <code>arcCenter()</code> 求圆心，以半径倒数得到局部曲率。Cusp 会先按运动方向翻转后一段再求圆。</li><li>包外调用：只由 <code>operator()</code> 调用。</li></ul><p><code>minimum_turning_radius</code> 在参数层被换成最大曲率。将半径设为零会得到无穷大上限，源码效果是关闭曲率惩罚；负半径没有显式校验，不应作为合法调参方式。</p><h3 id="_6-8-smoothercostfunction-adddistanceresidual" tabindex="-1">6.8 <code>SmootherCostFunction::addDistanceResidual()</code> <a class="header-anchor" href="#_6-8-smoothercostfunction-adddistanceresidual" aria-label="Permalink to &quot;6.8 `SmootherCostFunction::addDistanceResidual()`&quot;">​</a></h3><ul><li>作用：限制优化点偏离原路径。</li><li>输入：距离权重、当前优化坐标、原始坐标和残差引用。</li><li>输出：加入 <code>weight × squaredNorm(current-original)</code>。</li><li>数据流／回调：该项不读取 Costmap，也不关心前进／倒退。</li><li>包外调用：只由 <code>operator()</code> 调用。</li></ul><p><code>w_dist=0</code> 时路径可在其他残差推动下较自由地移动；增大它会强化原路径锚定。它不是绝对边界，仍会与其他残差共同折中。</p><h3 id="_6-9-smoothercostfunction-addcostresidual" tabindex="-1">6.9 <code>SmootherCostFunction::addCostResidual()</code> <a class="header-anchor" href="#_6-9-smoothercostfunction-addcostresidual" aria-label="Permalink to &quot;6.9 `SmootherCostFunction::addCostResidual()`&quot;">​</a></h3><ul><li>作用：根据 Costmap 把路径推离高代价区域。</li><li>输入：当前 Costmap 权重、三点坐标和残差引用。</li><li>输出：加入路径中心点或多个车体检查点的带权 Costmap 值平方。</li><li>数据流／回调：没有配置检查点时直接采样中心点；配置检查点时先用 <code>tangentDir()</code> 建立车体朝向，结合倒车标志确定正方向，再把每个机器人坐标系检查点变换到世界坐标并采样。</li><li>包外调用：只由 <code>operator()</code> 调用。</li></ul><p>Costmap 通过双三次插值以连续坐标读取，便于自动微分形成平滑梯度。这里使用的是 Costmap 字节值，不是二值碰撞结果；Footprint 也没有直接进入残差。长条形或不对称机器人可以通过检查点近似表达车体不同部位，但需要更多迭代，且最终仍应做包外碰撞检查。</p><p><img src="'+d+'" alt="下采样、Cusp 识别、权重渐变与 Ceres 残差块"></p><p><img src="'+s+'" alt="平滑、曲率、原路径距离与 Costmap 四维残差"></p><h2 id="七、几何工具的两个函数" tabindex="-1">七、几何工具的两个函数 <a class="header-anchor" href="#七、几何工具的两个函数" aria-label="Permalink to &quot;七、几何工具的两个函数&quot;">​</a></h2><h3 id="_7-1-arccenter" tabindex="-1">7.1 <code>arcCenter()</code> <a class="header-anchor" href="#_7-1-arccenter" aria-label="Permalink to &quot;7.1 `arcCenter()`&quot;">​</a></h3><ul><li>作用：求经过前一点、中心点和后一点的圆弧圆心。</li><li>输入：三个二维点和 <code>is_cusp</code> 标志。</li><li>输出：正常圆弧返回圆心；三点近共线时返回两个无穷大分量。</li><li>数据流／回调：Cusp 情况会把后一段反向，再求两条线段中垂线交点，使曲率对应机器人真实运动连续性。</li><li>包外调用：被 <code>addCurvatureResidual()</code> 和 <code>tangentDir()</code> 调用。</li></ul><h3 id="_7-2-tangentdir" tabindex="-1">7.2 <code>tangentDir()</code> <a class="header-anchor" href="#_7-2-tangentdir" aria-label="Permalink to &quot;7.2 `tangentDir()`&quot;">​</a></h3><ul><li>作用：计算中心点处的未定符号切向量。</li><li>输入：三个二维点和 <code>is_cusp</code> 标志。</li><li>输出：圆弧时返回半径的垂直向量；直线时返回首尾弦向量；极少数首尾重合情况返回前段的垂直向量。</li><li>数据流／回调：函数只给出切线方向轴，不决定正负。调用端再结合下一段位移和前进／倒退符号翻转。</li><li>包外调用：被 Costmap 检查点变换和输出朝向重建调用。</li></ul><h2 id="八、输入数据如何进入-ceres" tabindex="-1">八、输入数据如何进入 Ceres <a class="header-anchor" href="#八、输入数据如何进入-ceres" aria-label="Permalink to &quot;八、输入数据如何进入 Ceres&quot;">​</a></h2><h3 id="_8-1-path-pose-被拆成位置和运动方向" tabindex="-1">8.1 Path Pose 被拆成位置和运动方向 <a class="header-anchor" href="#_8-1-path-pose-被拆成位置和运动方向" aria-label="Permalink to &quot;8.1 Path Pose 被拆成位置和运动方向&quot;">​</a></h3><p>外层插件从每个四元数提取偏航角，构造单位朝向向量。当前 Pose 到下一 Pose 的位移与朝向点积小于零，就代表机器人面朝一个方向、路径却向相反方向延伸，源码把该段记为倒车。</p><p>Eigen 路径在求解前的第三维只保存 <code>+1</code> 或 <code>-1</code>。Ceres 参数块却只连接每个点内存中的前两个 double，也就是 <code>x、y</code>；方向符号不参与优化，只作为 Cusp 判断和朝向恢复的离散标签。</p><h3 id="_8-2-costmap-是每次请求时获取的快照" tabindex="-1">8.2 Costmap 是每次请求时获取的快照 <a class="header-anchor" href="#_8-2-costmap-是每次请求时获取的快照" aria-label="Permalink to &quot;8.2 Costmap 是每次请求时获取的快照&quot;">​</a></h3><p>插件在调用内部求解器前通过 <code>costmap_sub_-&gt;getCostmap()</code> 获取共享 Costmap。<code>buildProblem()</code> 用其字符数组创建 Ceres Grid，并为本次求解建立双三次插值器。优化期间没有 Costmap Topic 回调进入这个包，也不会在每次迭代重新抓取地图。</p><h3 id="_8-3-时间预算只约束-ceres-求解阶段" tabindex="-1">8.3 时间预算只约束 Ceres 求解阶段 <a class="header-anchor" href="#_8-3-时间预算只约束-ceres-求解阶段" aria-label="Permalink to &quot;8.3 时间预算只约束 Ceres 求解阶段&quot;">​</a></h3><p>Action Goal 的 Duration 被换成秒并写入 <code>SmootherParams::max_time</code>，随后成为 Ceres 的 <code>max_solver_time_in_seconds</code>。Path 转换、Costmap 网格创建、问题构建、贝塞尔上采样和消息写回都发生在这个选项之外，因此 Action 观察到的总耗时可能略大于给 Ceres 的上限。</p><h3 id="_8-4-ceres-参数块只优化二维坐标" tabindex="-1">8.4 Ceres 参数块只优化二维坐标 <a class="header-anchor" href="#_8-4-ceres-参数块只优化二维坐标" aria-label="Permalink to &quot;8.4 Ceres 参数块只优化二维坐标&quot;">​</a></h3><p>每个残差连接三组二维参数块。方向、Costmap 原点、分辨率、原始点位置、权重和倒车标志都是固定上下文。求解器通过自动微分得到相对于三点 <code>x、y</code> 的雅可比，最终只移动路径点，不直接优化 yaw。</p><h2 id="九、cusp-与下采样如何同时工作" tabindex="-1">九、Cusp 与下采样如何同时工作 <a class="header-anchor" href="#九、cusp-与下采样如何同时工作" aria-label="Permalink to &quot;九、Cusp 与下采样如何同时工作&quot;">​</a></h2><h3 id="_9-1-下采样不会跨过方向切换" tabindex="-1">9.1 下采样不会跨过方向切换 <a class="header-anchor" href="#_9-1-下采样不会跨过方向切换" aria-label="Permalink to &quot;9.1 下采样不会跨过方向切换&quot;">​</a></h3><p>普通点只有在索引距离未达到 <code>path_downsampling_factor</code> 时才跳过。Cusp 点永远不会因这个条件被跳过，而且采样间隔从 Cusp 重新开始。端点朝向保护开启时，靠近起点和目标的必要点也不能被跳过。</p><h3 id="_9-2-cusp-权重在两侧线性渐变" tabindex="-1">9.2 Cusp 权重在两侧线性渐变 <a class="header-anchor" href="#_9-2-cusp-权重在两侧线性渐变" aria-label="Permalink to &quot;9.2 Cusp 权重在两侧线性渐变&quot;">​</a></h3><p><code>cusp_zone_length</code> 被分成前后两个半区。遍历到 Cusp 前，源码用队列保留最近半区内已经创建的代价函数；确认 Cusp 后，回头提高这些函数的 Costmap 权重。遍历越过 Cusp 后，再按累计距离从中心权重逐渐降回普通权重。</p><h3 id="_9-3-相邻-cusp-取更强影响" tabindex="-1">9.3 相邻 Cusp 取更强影响 <a class="header-anchor" href="#_9-3-相邻-cusp-取更强影响" aria-label="Permalink to &quot;9.3 相邻 Cusp 取更强影响&quot;">​</a></h3><p>每个历史代价函数在更新前会读取当前 Costmap 权重。只有新权重更接近 Cusp 中心权重时才覆盖，这样两个 Cusp 区域重叠时，不会用较远 Cusp 的弱权重冲掉较近 Cusp 的强权重。</p><p><code>cusp_zone_length</code> 没有正值校验。需要 Cusp 加权时应保持它大于零，避免半区长度为零参与插值除法。</p><h2 id="十、输出路径如何恢复" tabindex="-1">十、输出路径如何恢复 <a class="header-anchor" href="#十、输出路径如何恢复" aria-label="Permalink to &quot;十、输出路径如何恢复&quot;">​</a></h2><h3 id="_10-1-优化点先得到稳定切向" tabindex="-1">10.1 优化点先得到稳定切向 <a class="header-anchor" href="#_10-1-优化点先得到稳定切向" aria-label="Permalink to &quot;10.1 优化点先得到稳定切向&quot;">​</a></h3><p>每组三个优化点通过 <code>tangentDir()</code> 得到中心点切向轴，再与下一段实际位移做点积确定符号。倒车段会额外乘方向符号，保证 Pose 朝向可以与路径位移相反，而不是把所有点强制朝向行进方向。</p><h3 id="_10-2-被跳过的点由三次贝塞尔补回" tabindex="-1">10.2 被跳过的点由三次贝塞尔补回 <a class="header-anchor" href="#_10-2-被跳过的点由三次贝塞尔补回" aria-label="Permalink to &quot;10.2 被跳过的点由三次贝塞尔补回&quot;">​</a></h3><p>两端优化点是贝塞尔端点，沿两端切向、按段长的 <code>0.4</code> 倍构造控制点。插值数量由原索引间隔与 <code>path_upsampling_factor</code> 共同决定。这样恢复出的点不仅密度连续，方向也能沿曲线逐点重算。</p><h3 id="_10-3-端点朝向由参数决定" tabindex="-1">10.3 端点朝向由参数决定 <a class="header-anchor" href="#_10-3-端点朝向由参数决定" aria-label="Permalink to &quot;10.3 端点朝向由参数决定&quot;">​</a></h3><p><code>keep_start_orientation</code> 或 <code>keep_goal_orientation</code> 开启时，输出直接使用输入 Path 的端点方向，同时问题构建阶段固定相邻点以支撑该方向。关闭时，源码根据平滑后路径切向重新计算端点朝向。</p><p><img src="'+n+'" alt="优化点、切向控制点、三次贝塞尔与朝向恢复"></p><h2 id="十一、包外调用与回调边界" tabindex="-1">十一、包外调用与回调边界 <a class="header-anchor" href="#十一、包外调用与回调边界" aria-label="Permalink to &quot;十一、包外调用与回调边界&quot;">​</a></h2><h3 id="_11-1-pluginlib-负责发现和创建" tabindex="-1">11.1 Pluginlib 负责发现和创建 <a class="header-anchor" href="#_11-1-pluginlib-负责发现和创建" aria-label="Permalink to &quot;11.1 Pluginlib 负责发现和创建&quot;">​</a></h3><p><code>nav2_constrained_smoother.xml</code> 把实现类导出为 <code>nav2_core::Smoother</code>，插件 ID 是 <code>nav2_constrained_smoother/ConstrainedSmoother</code>。Smoother Server 根据 <code>&lt;plugin_id&gt;.plugin</code> 参数创建实例，不需要在服务器代码中直接包含实现类。</p><h3 id="_11-2-lifecycle-由-smoother-server-统一驱动" tabindex="-1">11.2 Lifecycle 由 Smoother Server 统一驱动 <a class="header-anchor" href="#_11-2-lifecycle-由-smoother-server-统一驱动" aria-label="Permalink to &quot;11.2 Lifecycle 由 Smoother Server 统一驱动&quot;">​</a></h3><p>服务器配置时调用插件 <code>configure()</code>，激活、停用和清理阶段分别调用同名 Lifecycle 方法。这个包的后三个方法只写日志，真正的 Action Server、发布器、TF Listener、Costmap Subscriber 和 Footprint Subscriber 都由 <code>nav2_smoother</code> 创建和管理。</p><h3 id="_11-3-smoothpath-action-是公开运行入口" tabindex="-1">11.3 <code>SmoothPath</code> Action 是公开运行入口 <a class="header-anchor" href="#_11-3-smoothpath-action-是公开运行入口" aria-label="Permalink to &quot;11.3 `SmoothPath` Action 是公开运行入口&quot;">​</a></h3><p>Goal 输入包括：</p><ul><li><code>path</code>：待平滑路径。</li><li><code>smoother_id</code>：选择已加载插件。</li><li><code>max_smoothing_duration</code>：传给插件的求解时间预算。</li><li><code>check_for_collisions</code>：要求服务器在插件返回后检查结果。</li></ul><p>Result 输出包括：</p><ul><li><code>path</code>：平滑后的路径。</li><li><code>smoothing_duration</code>：服务器统计的总平滑耗时。</li><li><code>was_completed</code>：插件 <code>smooth()</code> 的布尔返回值。</li></ul><p>这些字段是并列接口，不代表执行序号。</p><h3 id="_11-4-bt-只负责搬运黑板数据" tabindex="-1">11.4 BT 只负责搬运黑板数据 <a class="header-anchor" href="#_11-4-bt-只负责搬运黑板数据" aria-label="Permalink to &quot;11.4 BT 只负责搬运黑板数据&quot;">​</a></h3><p><code>SmoothPathAction::on_tick()</code> 从 BT 输入端口填充 Goal，<code>on_success()</code> 把 Result Path、耗时和完成标志写回输出端口。BT 不理解 Ceres 权重，也不会替插件判断曲率或 Costmap 梯度。</p><h2 id="十二、参数应该如何理解" tabindex="-1">十二、参数应该如何理解 <a class="header-anchor" href="#十二、参数应该如何理解" aria-label="Permalink to &quot;十二、参数应该如何理解&quot;">​</a></h2><h3 id="_12-1-平滑、曲率与原路径锚定" tabindex="-1">12.1 平滑、曲率与原路径锚定 <a class="header-anchor" href="#_12-1-平滑、曲率与原路径锚定" aria-label="Permalink to &quot;12.1 平滑、曲率与原路径锚定&quot;">​</a></h3><ul><li><code>w_smooth</code> 增大会强烈抑制相邻段变化。</li><li><code>w_curve</code> 控制超过最大曲率后的惩罚强度。</li><li><code>minimum_turning_radius</code> 决定曲率上限，差分驱动或全向场景可按 README 用零关闭该项。</li><li><code>w_dist</code> 增大会把结果拉回原路径。</li></ul><p>这些量共同进入非线性最小二乘，而且残差还会被 Ceres 再平方，不能只按参数数值大小直接判断实际影响。有效调参必须固定路径、Costmap、采样因子和求解迭代数后比较输出。</p><h3 id="_12-2-costmap-与-cusp" tabindex="-1">12.2 Costmap 与 Cusp <a class="header-anchor" href="#_12-2-costmap-与-cusp" aria-label="Permalink to &quot;12.2 Costmap 与 Cusp&quot;">​</a></h3><ul><li><code>w_cost</code> 控制普通区域避障倾向。</li><li><code>w_cost_cusp_multiplier</code> 决定 Cusp 中心相对普通区域的倍数。</li><li><code>cusp_zone_length</code> 决定权重渐变覆盖的总路径长度。</li><li><code>cost_check_points</code> 用机器人坐标系三元组近似车体多个部位。</li></ul><p>检查点权重会被归一化，所以共同缩放所有检查点权重通常不会改变相对占比。应保证非空权重总和为正数，并在启用多个检查点后提高迭代预算。</p><h3 id="_12-3-路径采样" tabindex="-1">12.3 路径采样 <a class="header-anchor" href="#_12-3-路径采样" aria-label="Permalink to &quot;12.3 路径采样&quot;">​</a></h3><ul><li><code>path_downsampling_factor</code> 越大，Ceres 参数块越少，速度通常更快，但细节约束更稀。</li><li><code>path_upsampling_factor=0</code> 保留稀疏结果。</li><li><code>path_upsampling_factor=1</code> 按原索引密度恢复。</li><li>更大的上采样因子会生成更密路径，但不会增加 Ceres 真正优化过的节点数量。</li></ul><h3 id="_12-4-端点与倒车" tabindex="-1">12.4 端点与倒车 <a class="header-anchor" href="#_12-4-端点与倒车" aria-label="Permalink to &quot;12.4 端点与倒车&quot;">​</a></h3><ul><li><code>reversing_enabled</code> 依赖输入 Path 的有效朝向；没有可靠朝向的路径应关闭。</li><li><code>keep_start_orientation</code> 控制是否保留起点方向。</li><li><code>keep_goal_orientation</code> 控制是否保留目标方向。</li></ul><h3 id="_12-5-ceres-求解器" tabindex="-1">12.5 Ceres 求解器 <a class="header-anchor" href="#_12-5-ceres-求解器" aria-label="Permalink to &quot;12.5 Ceres 求解器&quot;">​</a></h3><ul><li><code>linear_solver_type</code> 当前只接受 <code>DENSE_QR</code> 与 <code>SPARSE_NORMAL_CHOLESKY</code>。</li><li><code>max_iterations</code> 是迭代上限。</li><li><code>gradient_tol</code>、<code>fn_tol</code>、<code>param_tol</code> 分别影响梯度、目标函数变化和参数变化停止条件。</li><li><code>debug_optimizer</code> 会输出逐迭代日志与完整求解报告。</li></ul><h2 id="十三、源码边界与风险" tabindex="-1">十三、源码边界与风险 <a class="header-anchor" href="#十三、源码边界与风险" aria-label="Permalink to &quot;十三、源码边界与风险&quot;">​</a></h2><h3 id="_13-1-重复坐标点不是合法输入形态" tabindex="-1">13.1 重复坐标点不是合法输入形态 <a class="header-anchor" href="#_13-1-重复坐标点不是合法输入形态" aria-label="Permalink to &quot;13.1 重复坐标点不是合法输入形态&quot;">​</a></h3><p>连续重复点会产生零长度段。源码用 <code>EPSILON</code> 保护部分长度比，但圆弧、切向、归一化和贝塞尔方向仍可能遇到退化几何。包 README 已明确不支持以重复坐标表达原地旋转的路径。</p><h3 id="_13-2-插件失败分支抛出的是异常指针" tabindex="-1">13.2 插件失败分支抛出的是异常指针 <a class="header-anchor" href="#_13-2-插件失败分支抛出的是异常指针" aria-label="Permalink to &quot;13.2 插件失败分支抛出的是异常指针&quot;">​</a></h3><p>外层 <code>ConstrainedSmoother::smooth()</code> 在内部求解返回 <code>false</code> 时执行 <code>throw new nav2_core::PlannerException(...)</code>。按 C++ 类型系统，这会抛出 <code>PlannerException *</code>，不是 <code>PlannerException</code> 对象。</p><p>包外 Smoother Server 捕获的是 <code>nav2_core::PlannerException &amp;</code> 和 <code>std::exception &amp;</code>，两者都不能匹配这个指针类型。因此，这条失败路径存在异常传播缺口。本文只记录当前事实，不把它误写成“服务器会正常捕获并终止 Goal”。</p><h3 id="_13-3-时间上限不等同于-was-completed-false" tabindex="-1">13.3 时间上限不等同于 <code>was_completed=false</code> <a class="header-anchor" href="#_13-3-时间上限不等同于-was-completed-false" aria-label="Permalink to &quot;13.3 时间上限不等同于 `was_completed=false`&quot;">​</a></h3><p>内部函数没有检查 Ceres <code>termination_type</code>。求解因时间上限停止后，如果 Summary 仍判定解可用且代价没有变差，插件就返回 <code>true</code>。所以当前实现中的 <code>was_completed</code> 更接近“是否接受求解结果”，不严格等于“是否在限制内完整收敛”。</p><h3 id="_13-4-costmap-残差不能代替最终碰撞检查" tabindex="-1">13.4 Costmap 残差不能代替最终碰撞检查 <a class="header-anchor" href="#_13-4-costmap-残差不能代替最终碰撞检查" aria-label="Permalink to &quot;13.4 Costmap 残差不能代替最终碰撞检查&quot;">​</a></h3><p>插件采样连续 Costmap 代价并做软惩罚，不把 Footprint 碰撞设成不可行约束。尤其在权重较小、迭代不足、检查点稀疏或插值曲线穿过高代价区时，仍应让 Smoother Server 执行 <code>check_for_collisions</code>。</p><h3 id="_13-5-参数校验并不完整" tabindex="-1">13.5 参数校验并不完整 <a class="header-anchor" href="#_13-5-参数校验并不完整" aria-label="Permalink to &quot;13.5 参数校验并不完整&quot;">​</a></h3><p>源码校验了检查点数组长度和线性求解器名称，但没有系统校验半径、Cusp 区域、采样因子、迭代数、容差和检查点权重总和。配置必须遵守算法隐含的有限值与正值前提。</p><h3 id="_13-6-tf-与-footprint-不属于当前优化核心" tabindex="-1">13.6 TF 与 Footprint 不属于当前优化核心 <a class="header-anchor" href="#_13-6-tf-与-footprint-不属于当前优化核心" aria-label="Permalink to &quot;13.6 TF 与 Footprint 不属于当前优化核心&quot;">​</a></h3><p>插件保存 TF 却没有使用，配置函数也忽略 Footprint Subscriber。不要从函数签名误判它会在包内变换 Path 或按完整 Footprint 建模；输入 Path 与 Costmap 必须已经处于可直接比较的坐标语义，完整 Footprint 检查发生在包外。</p><h2 id="十四、总结" tabindex="-1">十四、总结 <a class="header-anchor" href="#十四、总结" aria-label="Permalink to &quot;十四、总结&quot;">​</a></h2><h3 id="_14-1-用一条主线记住-29-个函数" tabindex="-1">14.1 用一条主线记住 29 个函数 <a class="header-anchor" href="#_14-1-用一条主线记住-29-个函数" aria-label="Permalink to &quot;14.1 用一条主线记住 29 个函数&quot;">​</a></h3><p><code>ConstrainedSmoother</code> 接住 Nav2 插件接口并完成消息转换，参数结构把 ROS 配置变成平滑权重与 Ceres Options，<code>Smoother</code> 把路径下采样成优化问题，<code>SmootherCostFunction</code> 用四维残差推动每个中间点，几何工具处理圆弧、切向和 Cusp，最后再用三次贝塞尔恢复路径密度与朝向。</p><p>它真正有价值的地方，不是“让折线看起来圆润”，而是把车辆最小转弯半径、障碍代价、前进／倒退切换和原路径保持放进同一套可微优化框架。它真正需要警惕的地方也同样明确：这是软约束、参数影响高度耦合、当前项目尚未启用，而且异常传播、时间完成语义和部分参数校验仍有源码边界。</p><p>理解这些边界后，调参不再是盲目放大某个权重，而是围绕输入路径质量、Costmap 梯度、Cusp 密度、采样规模、求解预算和包外碰撞验收共同设计整条平滑链。</p>',172)])])}const f=o(h,[["render",m]]);export{P as __pageData,f as default};
